-- DISPOSABLE TEST MODEL ONLY. No production provider, Flyway migration or credential.
-- __SCHEMA__ is generated by the local runner, never an HTTP/request identifier.
CREATE SCHEMA __SCHEMA__;
SET search_path = __SCHEMA__, pg_catalog;
CREATE TABLE users(id BIGINT PRIMARY KEY, telegram_user_id BIGINT UNIQUE NOT NULL);
CREATE TABLE audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);
CREATE TABLE clients(id BIGINT PRIMARY KEY, is_active BOOLEAN NOT NULL DEFAULT TRUE,
 archived_at TIMESTAMPTZ, lifecycle_version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE clubs(id BIGINT PRIMARY KEY);
CREATE TABLE client_clubs(client_id BIGINT REFERENCES clients(id) ON DELETE CASCADE,
 club_id BIGINT REFERENCES clubs(id) ON DELETE CASCADE, created_at TIMESTAMPTZ DEFAULT now(),
 PRIMARY KEY(client_id,club_id));
