-- The runner applies the UNCHANGED real V078 here before the remaining fixture.
-- V078_BOUNDARY
-- Hypothetical maintenance-purpose control head; intentionally NOT a real migration.
CREATE TABLE __SCHEMA__.probe_control_head(id INTEGER PRIMARY KEY, generation BIGINT NOT NULL,
 enabled BOOLEAN NOT NULL, owner_tg BIGINT NOT NULL, bundle_revision BIGINT NOT NULL);
INSERT INTO __SCHEMA__.probe_control_head VALUES(1,1,TRUE,7,1);
CREATE TABLE __SCHEMA__.probe_deadlock(id INTEGER PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO __SCHEMA__.probe_deadlock VALUES(1,0),(2,0);
CREATE FUNCTION __SCHEMA__.probe_assert(ok BOOLEAN, message TEXT) RETURNS VOID
 LANGUAGE plpgsql SET search_path = pg_catalog, __SCHEMA__, pg_temp AS $$
BEGIN IF ok IS DISTINCT FROM TRUE THEN RAISE EXCEPTION '%',message USING ERRCODE='P0001'; END IF; END $$;

-- Models the contract's checks/receipt path; NOT the Kotlin writer or a signed identity verifier.
-- Only synthetic actor 7 / bundle 1 / exact finite server fixture root+incarnation are admitted.
CREATE FUNCTION __SCHEMA__.probe_maintain(command_key TEXT, operation TEXT,
 expected_version BIGINT, expected_head BIGINT DEFAULT 1, fail_at TEXT DEFAULT '') RETURNS TEXT
 LANGUAGE plpgsql SET search_path = pg_catalog, __SCHEMA__, pg_temp AS $$
DECLARE h RECORD; r RECORD; b RECORD; previous RECORD; result_fence BIGINT;
DECLARE root UUID := '00000000-0000-0000-0000-000000000010';
DECLARE incarnation UUID := '00000000-0000-0000-0000-000000000011';
BEGIN
 SELECT * INTO h FROM __SCHEMA__.probe_control_head WHERE id=1 FOR SHARE;
 PERFORM __SCHEMA__.probe_assert(h.enabled AND h.generation=expected_head AND
  h.owner_tg=7 AND h.bundle_revision=1,'authority_denied');
 PERFORM __SCHEMA__.probe_assert(operation IN ('DISABLE','REVOKE','RETIRE'),'intent_denied');
 PERFORM id FROM __SCHEMA__.users WHERE id=1 FOR NO KEY UPDATE;
 PERFORM __SCHEMA__.probe_assert((SELECT telegram_user_id=7 FROM __SCHEMA__.users WHERE id=1),'actor_remapped');
 SELECT * INTO r FROM __SCHEMA__.target_bot_connections WHERE id=root FOR UPDATE;
 PERFORM __SCHEMA__.probe_assert(r.kind='PLATFORM' AND r.client_id IS NULL AND
  r.current_binding_id=incarnation AND r.version=r.generation,'root_denied');
 SELECT * INTO previous FROM __SCHEMA__.target_binding_commands
  WHERE actor_user_id=1 AND authority_connection_id='00000000-0000-0000-0000-000000000001'
  AND key_hash=pg_catalog.md5(command_key)||pg_catalog.md5(command_key);
 IF FOUND THEN
  PERFORM __SCHEMA__.probe_assert(previous.request_hash=pg_catalog.md5(operation||expected_version)||
   pg_catalog.md5(operation||expected_version),'idempotency_conflict');
  IF previous.result_version=r.version AND previous.result_generation=r.generation THEN RETURN 'REPLAY_CURRENT'; END IF;
  RETURN 'REPLAY_STALE';
 END IF;
 PERFORM __SCHEMA__.probe_assert(r.version=expected_version,'stale_cas');
 SELECT * INTO b FROM __SCHEMA__.target_bot_bindings WHERE id=incarnation;
 PERFORM __SCHEMA__.probe_assert(b.status IN ('PENDING','DISABLED'),'terminal_binding');
 IF operation='REVOKE' THEN
  UPDATE __SCHEMA__.target_credential_materials SET status='RETIRED',retired_at=now(),retired_audit_id=1
   WHERE root_id=root AND status='AVAILABLE';
  UPDATE __SCHEMA__.target_bot_bindings SET status='REVOKED',revoked_at=now(),revoked_audit_id=1 WHERE id=incarnation;
 ELSIF operation='RETIRE' THEN
  PERFORM __SCHEMA__.probe_assert(b.credential_ref IS NOT NULL,'missing_material');
  UPDATE __SCHEMA__.target_credential_materials SET status='RETIRED',retired_at=now(),retired_audit_id=1
   WHERE id=(SELECT material_id FROM __SCHEMA__.target_credential_revisions WHERE id=b.credential_ref);
  UPDATE __SCHEMA__.target_bot_bindings SET status='DISABLED',credential_ref=NULL WHERE id=incarnation;
 ELSE
  UPDATE __SCHEMA__.target_bot_bindings SET status='DISABLED' WHERE id=incarnation;
 END IF;
 -- Composite service behavior: child trigger(s), then final aggregate tick, never assume +1 total.
 UPDATE __SCHEMA__.target_bot_connections SET version=version+1,generation=generation+1 WHERE id=root;
 IF fail_at='audit' THEN RAISE EXCEPTION 'synthetic_audit_failure'; END IF;
 INSERT INTO __SCHEMA__.audit_log DEFAULT VALUES;
 SELECT version INTO result_fence FROM __SCHEMA__.target_bot_connections WHERE id=root;
 IF fail_at='receipt' THEN RAISE EXCEPTION 'synthetic_receipt_failure'; END IF;
 INSERT INTO __SCHEMA__.target_binding_commands(actor_user_id,authority_connection_id,key_hash,
 request_hash,root_id,binding_id,result_version,result_generation,audit_id)
 VALUES(1,'00000000-0000-0000-0000-000000000001',pg_catalog.md5(command_key)||pg_catalog.md5(command_key),
 pg_catalog.md5(operation||expected_version)||pg_catalog.md5(operation||expected_version),
 root,incarnation,result_fence,result_fence,1);
 RETURN 'APPLIED';
END $$;
